module case_range_1(input logic clk, rst, en, output logic [3:0] value);
  always_ff @(posedge clk or posedge rst) begin
    case (rst)
      1'b1: value <= 0;
      1'b0: begin
        case (value) inside
          [0:3]: begin
            case (en)
              1'b1: value <= value + 1;
              1'b0: value <= value;
            endcase
          end
          [4:7]: begin
            case (en)
              1'b1: value <= value - 1;
              1'b0: value <= value;
            endcase
          end
          [8:11]: value <= 4'b0101;
          [12:15]: value <= 0;
        endcase
      end
    endcase
  end
endmodule,"module case_range_1_assertions(input logic clk, rst, en, output logic [3:0] value)

module case_addr_decode(input logic clk, rst, enable, output logic [2:0] addr);
    always_ff @(posedge clk or posedge rst) begin
        case(rst)
            1'b1: addr <= 3'b000;
            1'b0: case(addr)
                      3'b000: case(enable)
                                  1'b1: addr <= 3'b001;
                                  1'b0: addr <= addr;
                                  default: addr <= addr;
                              endcase
                      3'b001, 3'b010, 3'b100: addr <= addr << 1;
                      3'b011: addr <= 3'b101;
                      3'b101: addr <= 3'b110;
                      3'b110, 3'b111: addr <= 3'b000;
                      default: addr <= 3'b000;
                  endcase
        endcase
    end
