module edge_detector_mealy (
    input logic clk,
    input logic rst_n,
    input logic din,
    output logic rising_edge
);

typedef enum logic {IDLE, HIGH} state_t;
state_t state, next_state;

// State register
always_ff @(posedge clk or negedge rst_n) begin
    case (rst_n)
        1'b0: state <= IDLE;
        1'b1: state <= next_state;
    endcase
end

// Next state and output logic (Mealy)
always_comb begin
    next_state = state;
    rising_edge = 1'b0;

    case (state)
        IDLE: begin
            case (din)
                1'b1: begin
                    next_state = HIGH;
                    rising_edge = 1'b1;  // Mealy: output depends on input
                end
            endcase
        end

        HIGH: begin
            case (din)
                1'b0: next_state = IDLE;
            endcase
        end
    endcase
end

endmodule,"module edge_detector_mealy_assertions(

module ethernet_packet_parser (
    input  logic        clk,
    input  logic        rst_n,

    // Input data stream
    input  logic        data_valid,
    input  logic [63:0] data_in,      // 64-bit wide data (8 bytes per cycle)
    input  logic        data_start,    // SOP (Start of Packet)
    input  logic        data_end,      // EOP (End of Packet)

    // Output parsed fields
    output logic [47:0] dest_mac,
    output logic [47:0] src_mac,
    output logic [15:0] ethertype,
    output logic [31:0] ipv4_src,
    output logic [31:0] ipv4_dst,
    output logic [15:0] tcp_src_port,
    output logic [15:0] tcp_dst_port,
    output logic [7:0]  ip_protocol,
    output logic        packet_valid,

    // Control outputs
    output logic        ipv4_detected,
    output logic        tcp_detected,
    output logic        udp_detected,
    output logic        vlan_detected,
    output logic        parsing_error
);

    // Block 1: Packet State Machine (Sequential)
    typedef enum logic [2:0] {
        WAIT_SOP   = 3'b000,
        MAC_DEST   = 3'b001,
        MAC_SRC    = 3'b010,
        VLAN_TAG   = 3'b011,
        ETHERTYPE  = 3'b100,
        IP_HEADER  = 3'b101,
        L4_HEADER  = 3'b110,
        PAYLOAD    = 3'b111
    } parse_state_t;

    parse_state_t current_state, next_state;
    logic [4:0] byte_offset;           // Byte position within current 64-bit word (0-7, but 5 bits to avoid overflow)
    logic [5:0] header_byte_count;     // Count of bytes processed in current header (up to 40 bytes for IP header)
    logic [47:0] temp_dest_mac;
    logic [47:0] temp_src_mac;
    logic [15:0] temp_ethertype;
    logic [31:0] temp_ipv4_src;
    logic [31:0] temp_ipv4_dst;
    logic [7:0]  temp_ip_protocol;
    logic [15:0] temp_tcp_src;
    logic [15:0] temp_tcp_dst;
    logic        has_vlan;

    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: current_state <= WAIT_SOP;
            1'b1: current_state <= next_state;
        endcase
    end

    // Block 2: Byte Position and Counters (Sequential)
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: begin
                byte_offset <= 5'b0;
                header_byte_count <= 6'b0;
            end
            1'b1: begin
                case (current_state)
                    WAIT_SOP: begin
                        case (data_start)
                            1'b1: begin
                                byte_offset <= 5'b0;
                                header_byte_count <= 6'b0;
                            end
                            default: begin
                                byte_offset <= byte_offset;
                                header_byte_count <= header_byte_count;
                            end
                        endcase
                    end

                    MAC_DEST, MAC_SRC, VLAN_TAG, ETHERTYPE, IP_HEADER, L4_HEADER: begin
                        case (data_valid)
                            1'b1: begin
                                byte_offset <= byte_offset + 5'd8;
                                header_byte_count <= header_byte_count + 6'd8;
                            end
                            default: begin
                                byte_offset <= byte_offset;
                                header_byte_count <= header_byte_count;
                            end
                        endcase
                    end

                    default: begin
                        byte_offset <= byte_offset;
                        header_byte_count <= header_byte_count;
                    end
                endcase
            end
        endcase
    end

    // Block 3: State Transition Logic (Case-only Combinational)
    always_comb begin
        next_state = current_state;

        case (current_state)
            WAIT_SOP: begin
                case (data_start)
                    1'b1: next_state = MAC_DEST;
                    default: next_state = WAIT_SOP;
                endcase
            end

            MAC_DEST: begin
                case ({data_valid, (header_byte_count >= 6'd6)})
                    2'b11: next_state = MAC_SRC;
                    default: next_state = MAC_DEST;
                endcase
            end

            MAC_SRC: begin
                case ({data_valid, (header_byte_count >= 6'd12)})
                    2'b11: next_state = ETHERTYPE;
                    default: next_state = MAC_SRC;
                endcase
            end

            ETHERTYPE: begin
                case (data_valid)
                    1'b1: begin
                        case (temp_ethertype)
                            16'h8100: next_state = VLAN_TAG;  // VLAN tag detected
                            default: next_state = IP_HEADER;
                        endcase
                    end
                    default: next_state = ETHERTYPE;
                endcase
            end

            VLAN_TAG: begin
                case ({data_valid, (header_byte_count >= 6'd4)})
                    2'b11: next_state = ETHERTYPE;
                    default: next_state = VLAN_TAG;
                endcase
            end

            IP_HEADER: begin
                case ({data_valid, (header_byte_count >= 6'd20)})
                    2'b11: next_state = L4_HEADER;
                    default: next_state = IP_HEADER;
                endcase
            end

            L4_HEADER: begin
                case (data_valid)
                    1'b1: begin
                        case ({temp_ip_protocol, (header_byte_count >= 6'd4)})
                            {8'd6, 1'b1}: next_state = PAYLOAD;  // TCP
                            {8'd17, 1'b1}: next_state = PAYLOAD;  // UDP
                            default: next_state = L4_HEADER;
                        endcase
                    end
                    default: next_state = L4_HEADER;
                endcase
            end

            PAYLOAD: begin
                case (data_end)
                    1'b1: next_state = WAIT_SOP;
                    default: next_state = PAYLOAD;
                endcase
            end

            default: begin
                case (data_end)
                    1'b1: next_state = WAIT_SOP;
                    default: next_state = current_state;
                endcase
            end
        endcase
    end

    // Block 4: MAC Address Extraction (Combinational with Byte Alignment)
    always_comb begin
        temp_dest_mac = dest_mac;
        temp_src_mac = src_mac;

        case (current_state)
            MAC_DEST: begin
                case (byte_offset[2:0])  // Extract based on byte alignment (lower 3 bits only)
                    3'b000: begin
                        temp_dest_mac[47:40] = data_in[63:56];
                        temp_dest_mac[39:32] = data_in[55:48];
                        temp_dest_mac[31:24] = data_in[47:40];
                        temp_dest_mac[23:16] = data_in[39:32];
                        temp_dest_mac[15:8]  = data_in[31:24];
                        temp_dest_mac[7:0]   = data_in[23:16];
                    end
                    3'b001: begin
                        temp_dest_mac[47:40] = data_in[55:48];
                        temp_dest_mac[39:32] = data_in[47:40];
                        temp_dest_mac[31:24] = data_in[39:32];
                        temp_dest_mac[23:16] = data_in[31:24];
                        temp_dest_mac[15:8]  = data_in[23:16];
                        temp_dest_mac[7:0]   = data_in[15:8];
                    end
                    default: temp_dest_mac = temp_dest_mac;
                endcase
            end

            MAC_SRC: begin
                case (byte_offset[2:0])
                    3'b000: begin
                        temp_src_mac[47:40] = data_in[63:56];
                        temp_src_mac[39:32] = data_in[55:48];
                        temp_src_mac[31:24] = data_in[47:40];
                        temp_src_mac[23:16] = data_in[39:32];
                        temp_src_mac[15:8]  = data_in[31:24];
                        temp_src_mac[7:0]   = data_in[23:16];
                    end
                    3'b001: begin
                        temp_src_mac[47:40] = data_in[55:48];
                        temp_src_mac[39:32] = data_in[47:40];
                        temp_src_mac[31:24] = data_in[39:32];
                        temp_src_mac[23:16] = data_in[31:24];
                        temp_src_mac[15:8]  = data_in[23:16];
                        temp_src_mac[7:0]   = data_in[15:8];
                    end
                    default: temp_src_mac = temp_src_mac;
                endcase
            end

            default: begin
                temp_dest_mac = temp_dest_mac;
                temp_src_mac = temp_src_mac;
            end
        endcase
    end

    // Block 5: Ethertype and VLAN Detection (Sequential Register)
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: begin
                temp_ethertype <= 16'b0;
                has_vlan <= 1'b0;
                vlan_detected <= 1'b0;
            end
            1'b1: begin
                case (current_state)
                    ETHERTYPE: begin
                        case (data_valid)
                            1'b1: begin
                                case (byte_offset[2:0])
                                    3'b000: begin
                                        temp_ethertype[15:8] <= data_in[63:56];
                                        temp_ethertype[7:0]  <= data_in[55:48];
                                    end
                                    3'b001: begin
                                        temp_ethertype[15:8] <= data_in[55:48];
                                        temp_ethertype[7:0]  <= data_in[47:40];
                                    end
                                    default: temp_ethertype <= temp_ethertype;
                                endcase
                            end
                            default: temp_ethertype <= temp_ethertype;
                        endcase

                        case (temp_ethertype)
                            16'h8100: begin
                                has_vlan <= 1'b1;
                                vlan_detected <= 1'b1;
                            end
                            default: begin
                                has_vlan <= has_vlan;
                                vlan_detected <= vlan_detected;
                            end
                        endcase
                    end

                    default: begin
                        temp_ethertype <= temp_ethertype;
                        has_vlan <= has_vlan;
                        vlan_detected <= vlan_detected;
                    end
                endcase
            end
        endcase
    end

    // Block 6: IPv4 Header Extraction (Sequential with Byte Selection)
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: begin
                temp_ipv4_src <= 32'b0;
                temp_ipv4_dst <= 32'b0;
                temp_ip_protocol <= 8'b0;
                ipv4_detected <= 1'b0;
            end
            1'b1: begin
                case (current_state)
                    IP_HEADER: begin
                        case (header_byte_count)
                            6'd8: begin  // Protocol field at offset 9
                                case (byte_offset[2:0])
                                    3'b000: temp_ip_protocol <= data_in[55:48];
                                    3'b001: temp_ip_protocol <= data_in[47:40];
                                    default: temp_ip_protocol <= temp_ip_protocol;
                                endcase
                            end

                            6'd12: begin  // Source IP at offset 12
                                case (byte_offset[2:0])
                                    3'b000: begin
                                        temp_ipv4_src[31:24] <= data_in[63:56];
                                        temp_ipv4_src[23:16] <= data_in[55:48];
                                        temp_ipv4_src[15:8]  <= data_in[47:40];
                                        temp_ipv4_src[7:0]   <= data_in[39:32];
                                    end
                                    3'b001: begin
                                        temp_ipv4_src[31:24] <= data_in[55:48];
                                        temp_ipv4_src[23:16] <= data_in[47:40];
                                        temp_ipv4_src[15:8]  <= data_in[39:32];
                                        temp_ipv4_src[7:0]   <= data_in[31:24];
                                    end
                                    default: temp_ipv4_src <= temp_ipv4_src;
                                endcase
                            end

                            6'd16: begin  // Destination IP at offset 16
                                case (byte_offset[2:0])
                                    3'b000: begin
                                        temp_ipv4_dst[31:24] <= data_in[63:56];
                                        temp_ipv4_dst[23:16] <= data_in[55:48];
                                        temp_ipv4_dst[15:8]  <= data_in[47:40];
                                        temp_ipv4_dst[7:0]   <= data_in[39:32];
                                    end
                                    3'b001: begin
                                        temp_ipv4_dst[31:24] <= data_in[55:48];
                                        temp_ipv4_dst[23:16] <= data_in[47:40];
                                        temp_ipv4_dst[15:8]  <= data_in[39:32];
                                        temp_ipv4_dst[7:0]   <= data_in[31:24];
                                    end
                                    default: temp_ipv4_dst <= temp_ipv4_dst;
                                endcase
                            end

                            default: begin
                                temp_ipv4_src <= temp_ipv4_src;
                                temp_ipv4_dst <= temp_ipv4_dst;
                                temp_ip_protocol <= temp_ip_protocol;
                            end
                        endcase

                        case (temp_ethertype)
                            16'h0800: ipv4_detected <= 1'b1;
                            default: ipv4_detected <= ipv4_detected;
                        endcase
                    end

                    default: begin
                        temp_ipv4_src <= temp_ipv4_src;
                        temp_ipv4_dst <= temp_ipv4_dst;
                        temp_ip_protocol <= temp_ip_protocol;
                        ipv4_detected <= ipv4_detected;
                    end
                endcase
            end
        endcase
    end

    // Block 7: TCP/UDP Port Extraction (Sequential)
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: begin
                temp_tcp_src <= 16'b0;
                temp_tcp_dst <= 16'b0;
                tcp_detected <= 1'b0;
                udp_detected <= 1'b0;
            end
            1'b1: begin
                case (current_state)
                    L4_HEADER: begin
                        case (header_byte_count)
                            6'd0: begin  // Source port at offset 0
                                case (byte_offset[2:0])
                                    3'b000: begin
                                        temp_tcp_src[15:8] <= data_in[63:56];
                                        temp_tcp_src[7:0]  <= data_in[55:48];
                                    end
                                    3'b001: begin
                                        temp_tcp_src[15:8] <= data_in[55:48];
                                        temp_tcp_src[7:0]  <= data_in[47:40];
                                    end
                                    default: temp_tcp_src <= temp_tcp_src;
                                endcase
                            end

                            6'd2: begin  // Destination port at offset 2
                                case (byte_offset[2:0])
                                    3'b000: begin
                                        temp_tcp_dst[15:8] <= data_in[63:56];
                                        temp_tcp_dst[7:0]  <= data_in[55:48];
                                    end
                                    3'b001: begin
                                        temp_tcp_dst[15:8] <= data_in[55:48];
                                        temp_tcp_dst[7:0]  <= data_in[47:40];
                                    end
                                    default: temp_tcp_dst <= temp_tcp_dst;
                                endcase
                            end

                            default: begin
                                temp_tcp_src <= temp_tcp_src;
                                temp_tcp_dst <= temp_tcp_dst;
                            end
                        endcase

                        case (temp_ip_protocol)
                            8'd6:  tcp_detected <= 1'b1;
                            8'd17: udp_detected <= 1'b1;
                            default: begin
                                tcp_detected <= tcp_detected;
                                udp_detected <= udp_detected;
                            end
                        endcase
                    end

                    default: begin
                        temp_tcp_src <= temp_tcp_src;
                        temp_tcp_dst <= temp_tcp_dst;
                        tcp_detected <= tcp_detected;
                        udp_detected <= udp_detected;
                    end
                endcase
            end
        endcase
    end

    // Block 8: Output Assignment and Error Detection (Case-only Combinational)
    always_comb begin
        dest_mac = temp_dest_mac;
        src_mac = temp_src_mac;
        ethertype = temp_ethertype;
        ipv4_src = temp_ipv4_src;
        ipv4_dst = temp_ipv4_dst;
        tcp_src_port = temp_tcp_src;
        tcp_dst_port = temp_tcp_dst;
        ip_protocol = temp_ip_protocol;
        packet_valid = 1'b0;
        parsing_error = 1'b0;

        case (current_state)
            PAYLOAD: begin
                case (data_end)
                    1'b1: packet_valid = 1'b1;
                    default: packet_valid = 1'b0;
                endcase
            end

            default: begin
                case (current_state == WAIT_SOP && data_end && !data_start)
                    1'b1: parsing_error = 1'b1;
                    default: parsing_error = 1'b0;
                endcase
            end
        endcase
    end

endmodule,"module ethernet_packet_parser_assertions(

module pcie_tlp_decoder (
    input  logic        clk,
    input  logic        rst_n,

    // TLP Input Stream
    input  logic        tlp_valid,
    input  logic [63:0] tlp_data,      // 64-bit TLP data
    input  logic        tlp_start,      // Start of TLP
    input  logic        tlp_end,        // End of TLP
    input  logic [2:0]  tlp_dw_count,   // Double-word count (1-4 DWs for header)

    // Decoded TLP Header Fields
    output logic [7:0]  tlp_fmt_type,   // Format and Type (bits 0-7)
    output logic [9:0]  tlp_length,     // Payload length in DWs
    output logic [15:0] tlp_requester_id, // Requester ID (Bus:Device:Function)
    output logic [15:0] tlp_completer_id, // Completer ID
    output logic [7:0]  tlp_tag,        // Transaction Tag
    output logic [31:0] tlp_address,    // Address for memory transactions
    output logic [31:0] tlp_data_payload, // First 4 bytes of data payload
    output logic [3:0]  tlp_first_be,   // First DW Byte Enables
    output logic [3:0]  tlp_last_be,    // Last DW Byte Enables

    // Transaction Type Flags
    output logic        tlp_mem_read,
    output logic        tlp_mem_write,
    output logic        tlp_cfg_read,
    output logic        tlp_cfg_write,
    output logic        tlp_completion,
    output logic        tlp_completion_data,

    // Error Detection
    output logic        tlp_parity_error,
    output logic        tlp_format_error,
    output logic        tlp_decode_done
);

    // Block 1: TLP State Machine (Sequential)
    typedef enum logic [2:0] {
        IDLE          = 3'b000,
        HEADER_DW0    = 3'b001,
        HEADER_DW1    = 3'b010,
        HEADER_DW2    = 3'b011,
        HEADER_DW3    = 3'b100,
        DATA_PAYLOAD  = 3'b101,
        DECODE_DONE   = 3'b110,
        ERROR         = 3'b111
    } tlp_state_t;

    tlp_state_t current_state, next_state;

    // Header storage registers
    logic [31:0] header_dw0;
    logic [31:0] header_dw1;
    logic [31:0] header_dw2;
    logic [31:0] header_dw3;
    logic [31:0] payload_data;

    // Decoded fields
    logic [7:0]  decoded_fmt_type;
    logic [9:0]  decoded_length;
    logic [15:0] decoded_requester_id;
    logic [15:0] decoded_completer_id;
    logic [7:0]  decoded_tag;
    logic [31:0] decoded_address;
    logic [3:0]  decoded_first_be;
    logic [3:0]  decoded_last_be;
    logic [31:0] decoded_payload;

    // Control signals
    logic [1:0]  header_dw_counter;
    logic        is_3dw_header;
    logic        is_4dw_header;
    logic        has_payload;
    logic [9:0]  payload_dw_remaining;

    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: current_state <= IDLE;
            1'b1: current_state <= next_state;
        endcase
    end

    // Block 2: Header Counter and Payload Tracker (Sequential)
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: begin
                header_dw_counter <= 2'b0;
                payload_dw_remaining <= 10'b0;
            end
            1'b1: begin
                case (current_state)
                    IDLE: begin
                        case (tlp_start)
                            1'b1: begin
                                header_dw_counter <= 2'b0;
                                payload_dw_remaining <= 10'b0;
                            end
                            default: begin
                                header_dw_counter <= header_dw_counter;
                                payload_dw_remaining <= payload_dw_remaining;
                            end
                        endcase
                    end

                    HEADER_DW0, HEADER_DW1, HEADER_DW2, HEADER_DW3: begin
                        case (tlp_valid)
                            1'b1: begin
                                header_dw_counter <= header_dw_counter + 2'd1;
                                payload_dw_remaining <= payload_dw_remaining;
                            end
                            default: begin
                                header_dw_counter <= header_dw_counter;
                                payload_dw_remaining <= payload_dw_remaining;
                            end
                        endcase
                    end

                    DATA_PAYLOAD: begin
                        case (tlp_valid)
                            1'b1: begin
                                header_dw_counter <= header_dw_counter;
                                payload_dw_remaining <= payload_dw_remaining - 10'd2;  // 2 DWs per cycle
                            end
                            default: begin
                                header_dw_counter <= header_dw_counter;
                                payload_dw_remaining <= payload_dw_remaining;
                            end
                        endcase
                    end

                    default: begin
                        header_dw_counter <= header_dw_counter;
                        payload_dw_remaining <= payload_dw_remaining;
                    end
                endcase
            end
        endcase
    end

    // Block 3: Header Type Detection (Combinational)
    always_comb begin
        is_3dw_header = 1'b0;
        is_4dw_header = 1'b0;
        has_payload = 1'b0;

        case (header_dw0[30:24])  // Fmt[2:0] and Type[4:0] bits
            8'b000_00000: begin  // MRd - Memory Read (3DW header)
                is_3dw_header = 1'b1;
                has_payload = 1'b0;
            end
            8'b001_00000: begin  // MRdLk - Memory Read Locked (3DW)
                is_3dw_header = 1'b1;
                has_payload = 1'b0;
            end
            8'b010_00000: begin  // MWr - Memory Write (3DW with payload)
                is_3dw_header = 1'b1;
                has_payload = 1'b1;
            end
            8'b100_00100: begin  // CfgRd0 - Configuration Read (3DW)
                is_3dw_header = 1'b1;
                has_payload = 1'b0;
            end
            8'b101_00100: begin  // CfgWr0 - Configuration Write (3DW with payload)
                is_3dw_header = 1'b1;
                has_payload = 1'b1;
            end
            8'b010_01010: begin  // Cpl - Completion without data (3DW)
                is_3dw_header = 1'b1;
                has_payload = 1'b0;
            end
            8'b010_01011: begin  // CplD - Completion with data (3DW with payload)
                is_3dw_header = 1'b1;
                has_payload = 1'b1;
            end
            8'b010_00001: begin  // MRd64 - Memory Read 64-bit (4DW header)
                is_4dw_header = 1'b1;
                has_payload = 1'b0;
            end
            8'b011_00001: begin  // MWr64 - Memory Write 64-bit (4DW with payload)
                is_4dw_header = 1'b1;
                has_payload = 1'b1;
            end
            default: begin
                is_3dw_header = 1'b0;
                is_4dw_header = 1'b0;
                has_payload = 1'b0;
            end
        endcase
    end

    // Block 4: State Transition Logic (Case-only Combinational)
    always_comb begin
        next_state = current_state;

        case (current_state)
            IDLE: begin
                case (tlp_start)
                    1'b1: next_state = HEADER_DW0;
                    default: next_state = IDLE;
                endcase
            end

            HEADER_DW0: begin
                case (tlp_valid)
                    1'b1: next_state = HEADER_DW1;
                    default: next_state = HEADER_DW0;
                endcase
            end

            HEADER_DW1: begin
                case (tlp_valid)
                    1'b1: begin
                        case (is_3dw_header)
                            1'b1: begin
                                case (has_payload)
                                    1'b1: next_state = DATA_PAYLOAD;
                                    default: next_state = DECODE_DONE;
                                endcase
                            end
                            default: next_state = HEADER_DW2;
                        endcase
                    end
                    default: next_state = HEADER_DW1;
                endcase
            end

            HEADER_DW2: begin
                case (tlp_valid)
                    1'b1: begin
                        case (is_4dw_header)
                            1'b1: next_state = HEADER_DW3;
                            default: begin
                                case (has_payload)
                                    1'b1: next_state = DATA_PAYLOAD;
                                    default: next_state = DECODE_DONE;
                                endcase
                            end
                        endcase
                    end
                    default: next_state = HEADER_DW2;
                endcase
            end

            HEADER_DW3: begin
                case (tlp_valid)
                    1'b1: begin
                        case (has_payload)
                            1'b1: next_state = DATA_PAYLOAD;
                            default: next_state = DECODE_DONE;
                        endcase
                    end
                    default: next_state = HEADER_DW3;
                endcase
            end

            DATA_PAYLOAD: begin
                case ({tlp_end, (payload_dw_remaining <= 10'd2)})
                    2'b10, 2'b11: next_state = DECODE_DONE;
                    default: next_state = DATA_PAYLOAD;
                endcase
            end

            DECODE_DONE: begin
                case (tlp_end)
                    1'b1: next_state = IDLE;
                    default: next_state = DECODE_DONE;
                endcase
            end

            ERROR: begin
                case (tlp_end)
                    1'b1: next_state = IDLE;
                    default: next_state = ERROR;
                endcase
            end

            default: next_state = ERROR;
        endcase
    end

    // Block 5: Header Data Capture (Sequential)
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: begin
                header_dw0 <= 32'b0;
                header_dw1 <= 32'b0;
                header_dw2 <= 32'b0;
                header_dw3 <= 32'b0;
            end
            1'b1: begin
                case (current_state)
                    HEADER_DW0: begin
                        case (tlp_valid)
                            1'b1: header_dw0 <= tlp_data[63:32];  // First DW is upper 32 bits
                            default: header_dw0 <= header_dw0;
                        endcase
                    end

                    HEADER_DW1: begin
                        case (tlp_valid)
                            1'b1: header_dw1 <= tlp_data[31:0];   // Second DW is lower 32 bits
                            default: header_dw1 <= header_dw1;
                        endcase
                    end

                    HEADER_DW2: begin
                        case (tlp_valid)
                            1'b1: header_dw2 <= tlp_data[63:32];
                            default: header_dw2 <= header_dw2;
                        endcase
                    end

                    HEADER_DW3: begin
                        case (tlp_valid)
                            1'b1: header_dw3 <= tlp_data[31:0];
                            default: header_dw3 <= header_dw3;
                        endcase
                    end

                    default: begin
                        header_dw0 <= header_dw0;
                        header_dw1 <= header_dw1;
                        header_dw2 <= header_dw2;
                        header_dw3 <= header_dw3;
                    end
                endcase
            end
        endcase
    end

    // Block 6: Payload Data Capture (Sequential)
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: payload_data <= 32'b0;
            1'b1: begin
                case (current_state)
                    DATA_PAYLOAD: begin
                        case (tlp_valid)
                            1'b1: payload_data <= tlp_data[31:0];  // Capture first 4 bytes of payload
                            default: payload_data <= payload_data;
                        endcase
                    end
                    default: payload_data <= payload_data;
                endcase
            end
        endcase
    end

    // Block 7: Header Field Decoding (Combinational)
    always_comb begin
        decoded_fmt_type = 8'b0;
        decoded_length = 10'b0;
        decoded_requester_id = 16'b0;
        decoded_completer_id = 16'b0;
        decoded_tag = 8'b0;
        decoded_address = 32'b0;
        decoded_first_be = 4'b0;
        decoded_last_be = 4'b0;
        decoded_payload = 32'b0;

        case (current_state)
            DECODE_DONE: begin
                // Fmt and Type fields
                decoded_fmt_type = header_dw0[30:23];

                // Length field (in DWs)
                decoded_length = header_dw0[9:0];

                // Requester ID (Bus:Device:Function)
                decoded_requester_id = header_dw1[31:16];

                case (is_3dw_header)
                    1'b1: begin
                        // Tag field
                        decoded_tag = header_dw1[7:0];

                        // Address for 32-bit addressing
                        decoded_address = {header_dw2[31:2], 2'b0};

                        // First and Last DW Byte Enables
                        decoded_first_be = header_dw1[15:12];
                        decoded_last_be = header_dw1[11:8];

                        // Completer ID for completions
                        case (header_dw0[24:20])  // Type field
                            5'b01010, 5'b01011: begin  // Cpl or CplD
                                decoded_completer_id = header_dw2[31:16];
                            end
                            default: decoded_completer_id = 16'b0;
                        endcase
                    end
                    default: begin  // 4DW header
                        // Tag field
                        decoded_tag = header_dw2[7:0];

                        // Address for 64-bit addressing
                        decoded_address = {header_dw2[31:2], header_dw3[31:0], 2'b0};

                        // First and Last DW Byte Enables
                        decoded_first_be = header_dw2[15:12];
                        decoded_last_be = header_dw2[11:8];
                    end
                endcase

                // Payload data
                decoded_payload = payload_data;
            end

            default: begin
                decoded_fmt_type = decoded_fmt_type;
                decoded_length = decoded_length;
                decoded_requester_id = decoded_requester_id;
                decoded_completer_id = decoded_completer_id;
                decoded_tag = decoded_tag;
                decoded_address = decoded_address;
                decoded_first_be = decoded_first_be;
                decoded_last_be = decoded_last_be;
                decoded_payload = decoded_payload;
            end
        endcase
    end

    // Block 8: Transaction Type Detection (Combinational)
    always_comb begin
        tlp_mem_read = 1'b0;
        tlp_mem_write = 1'b0;
        tlp_cfg_read = 1'b0;
        tlp_cfg_write = 1'b0;
        tlp_completion = 1'b0;
        tlp_completion_data = 1'b0;

        case (decoded_fmt_type)
            8'b000_00000, 8'b001_00000: tlp_mem_read = 1'b1;   // MRd, MRdLk
            8'b010_00000: tlp_mem_write = 1'b1;                // MWr
            8'b100_00100: tlp_cfg_read = 1'b1;                 // CfgRd0
            8'b101_00100: tlp_cfg_write = 1'b1;                // CfgWr0
            8'b010_01010: tlp_completion = 1'b1;               // Cpl
            8'b010_01011: begin                                // CplD
                tlp_completion = 1'b1;
                tlp_completion_data = 1'b1;
            end
            default: begin
                tlp_mem_read = 1'b0;
                tlp_mem_write = 1'b0;
                tlp_cfg_read = 1'b0;
                tlp_cfg_write = 1'b0;
                tlp_completion = 1'b0;
                tlp_completion_data = 1'b0;
            end
        endcase
    end

    // Block 9: Output Assignment and Error Detection (Combinational)
    always_comb begin
        tlp_fmt_type = decoded_fmt_type;
        tlp_length = decoded_length;
        tlp_requester_id = decoded_requester_id;
        tlp_completer_id = decoded_completer_id;
        tlp_tag = decoded_tag;
        tlp_address = decoded_address;
        tlp_data_payload = decoded_payload;
        tlp_first_be = decoded_first_be;
        tlp_last_be = decoded_last_be;
        tlp_decode_done = 1'b0;
        tlp_parity_error = 1'b0;
        tlp_format_error = 1'b0;

        case (current_state)
            DECODE_DONE: begin
                tlp_decode_done = 1'b1;

                // Format error detection
                case ({is_3dw_header, is_4dw_header, (tlp_dw_count >= 3'd3)})
                    3'b100: tlp_format_error = 1'b0;
                    3'b010: tlp_format_error = 1'b0;
                    default: tlp_format_error = 1'b1;
                endcase

                // Parity error detection (simplified - would check ECRC in real design)
                case (^header_dw0 ^ ^header_dw1 ^ ^header_dw2 ^ ^header_dw3)
                    1'b1: tlp_parity_error = 1'b1;
                    default: tlp_parity_error = 1'b0;
                endcase
            end

            ERROR: begin
                tlp_format_error = 1'b1;
                tlp_decode_done = 1'b1;
            end

            default: begin
                tlp_decode_done = 1'b0;
                tlp_parity_error = 1'b0;
                tlp_format_error = 1'b0;
            end
        endcase
    end

endmodule,"module pcie_tlp_decoder_assertions(

module video_csc (
    input  logic        clk,
    input  logic        rst_n,
    input  logic [23:0] rgb_pixel,       // RGB 888 {R[7:0], G[7:0], B[7:0]}
    input  logic        pixel_valid,
    output logic [29:0] ycbcr_pixel,     // YCbCr 4:4:4 {Y[9:0], Cb[9:0], Cr[9:0]}
    output logic [9:0]  h_sync, v_sync,
    output logic        h_blank, v_blank
);

    // Block 1: Color Space Conversion Coefficients (Fixed-Point)
    // Using 16-bit fixed-point with 8 fractional bits (Q8.8)
    // Y  = (77*R + 150*G + 29*B) >> 8
    // Cb = (-43*R - 85*G + 128*B + 32768) >> 8
    // Cr = (128*R - 107*G - 21*B + 32768) >> 8

    // Block 1a: RGB Component Extraction
    logic [7:0] R, G, B;

    always_comb begin
        R = rgb_pixel[23:16];
        G = rgb_pixel[15:8];
        B = rgb_pixel[7:0];
    end

    // Block 2: Y Component Calculation (Sequential Pipeline Stage 1)
    logic [15:0] R_mul_77, G_mul_150, B_mul_29;
    logic [15:0] y_sum_stage1;

    always_comb begin
        // Multiply using case-based partial products (no multipliers)
        case (R)
            8'd0:   R_mul_77 = 16'd0;
            8'd1:   R_mul_77 = 16'd77;
            8'd2:   R_mul_77 = 16'd154;
            8'd3:   R_mul_77 = 16'd231;
            8'd4:   R_mul_77 = 16'd308;
            8'd5:   R_mul_77 = 16'd385;
            8'd6:   R_mul_77 = 16'd462;
            8'd7:   R_mul_77 = 16'd539;
            8'd8:   R_mul_77 = 16'd616;
            8'd9:   R_mul_77 = 16'd693;
            8'd10:  R_mul_77 = 16'd770;
            8'd11:  R_mul_77 = 16'd847;
            8'd12:  R_mul_77 = 16'd924;
            8'd13:  R_mul_77 = 16'd1001;
            8'd14:  R_mul_77 = 16'd1078;
            8'd15:  R_mul_77 = 16'd1155;
            8'd16:  R_mul_77 = 16'd1232;
            8'd17:  R_mul_77 = 16'd1309;
            8'd18:  R_mul_77 = 16'd1386;
            8'd19:  R_mul_77 = 16'd1463;
            8'd20:  R_mul_77 = 16'd1540;
            8'd21:  R_mul_77 = 16'd1617;
            8'd22:  R_mul_77 = 16'd1694;
            8'd23:  R_mul_77 = 16'd1771;
            8'd24:  R_mul_77 = 16'd1848;
            8'd25:  R_mul_77 = 16'd1925;
            8'd26:  R_mul_77 = 16'd2002;
            8'd27:  R_mul_77 = 16'd2079;
            8'd28:  R_mul_77 = 16'd2156;
            8'd29:  R_mul_77 = 16'd2233;
            8'd30:  R_mul_77 = 16'd2310;
            8'd31:  R_mul_77 = 16'd2387;
            8'd32:  R_mul_77 = 16'd2464;
            8'd33:  R_mul_77 = 16'd2541;
            8'd34:  R_mul_77 = 16'd2618;
            8'd35:  R_mul_77 = 16'd2695;
            8'd36:  R_mul_77 = 16'd2772;
            8'd37:  R_mul_77 = 16'd2849;
            8'd38:  R_mul_77 = 16'd2926;
            8'd39:  R_mul_77 = 16'd3003;
            8'd40:  R_mul_77 = 16'd3080;
            8'd41:  R_mul_77 = 16'd3157;
            8'd42:  R_mul_77 = 16'd3234;
            8'd43:  R_mul_77 = 16'd3311;
            8'd44:  R_mul_77 = 16'd3388;
            8'd45:  R_mul_77 = 16'd3465;
            8'd46:  R_mul_77 = 16'd3542;
            8'd47:  R_mul_77 = 16'd3619;
            8'd48:  R_mul_77 = 16'd3696;
            8'd49:  R_mul_77 = 16'd3773;
            8'd50:  R_mul_77 = 16'd3850;
            8'd51:  R_mul_77 = 16'd3927;
            8'd52:  R_mul_77 = 16'd4004;
            8'd53:  R_mul_77 = 16'd4081;
            8'd54:  R_mul_77 = 16'd4158;
            8'd55:  R_mul_77 = 16'd4235;
            8'd56:  R_mul_77 = 16'd4312;
            8'd57:  R_mul_77 = 16'd4389;
            8'd58:  R_mul_77 = 16'd4466;
            8'd59:  R_mul_77 = 16'd4543;
            8'd60:  R_mul_77 = 16'd4620;
            8'd61:  R_mul_77 = 16'd4697;
            8'd62:  R_mul_77 = 16'd4774;
            8'd63:  R_mul_77 = 16'd4851;
            8'd64:  R_mul_77 = 16'd4928;
            8'd65:  R_mul_77 = 16'd5005;
            8'd66:  R_mul_77 = 16'd5082;
            8'd67:  R_mul_77 = 16'd5159;
            8'd68:  R_mul_77 = 16'd5236;
            8'd69:  R_mul_77 = 16'd5313;
            8'd70:  R_mul_77 = 16'd5390;
            8'd71:  R_mul_77 = 16'd5467;
            8'd72:  R_mul_77 = 16'd5544;
            8'd73:  R_mul_77 = 16'd5621;
            8'd74:  R_mul_77 = 16'd5698;
            8'd75:  R_mul_77 = 16'd5775;
            8'd76:  R_mul_77 = 16'd5852;
            8'd77:  R_mul_77 = 16'd5929;
            8'd78:  R_mul_77 = 16'd6006;
            8'd79:  R_mul_77 = 16'd6083;
            8'd80:  R_mul_77 = 16'd6160;
            8'd81:  R_mul_77 = 16'd6237;
            8'd82:  R_mul_77 = 16'd6314;
            8'd83:  R_mul_77 = 16'd6391;
            8'd84:  R_mul_77 = 16'd6468;
            8'd85:  R_mul_77 = 16'd6545;
            8'd86:  R_mul_77 = 16'd6622;
            8'd87:  R_mul_77 = 16'd6699;
            8'd88:  R_mul_77 = 16'd6776;
            8'd89:  R_mul_77 = 16'd6853;
            8'd90:  R_mul_77 = 16'd6930;
            8'd91:  R_mul_77 = 16'd7007;
            8'd92:  R_mul_77 = 16'd7084;
            8'd93:  R_mul_77 = 16'd7161;
            8'd94:  R_mul_77 = 16'd7238;
            8'd95:  R_mul_77 = 16'd7315;
            8'd96:  R_mul_77 = 16'd7392;
            8'd97:  R_mul_77 = 16'd7469;
            8'd98:  R_mul_77 = 16'd7546;
            8'd99:  R_mul_77 = 16'd7623;
            8'd100: R_mul_77 = 16'd7700;
            default: R_mul_77 = R * 77;  // For remaining values, but synthesizer will optimize
        endcase

        case (G)
            8'd0:   G_mul_150 = 16'd0;
            8'd1:   G_mul_150 = 16'd150;
            8'd2:   G_mul_150 = 16'd300;
            8'd3:   G_mul_150 = 16'd450;
            8'd4:   G_mul_150 = 16'd600;
            8'd5:   G_mul_150 = 16'd750;
            8'd6:   G_mul_150 = 16'd900;
            8'd7:   G_mul_150 = 16'd1050;
            8'd8:   G_mul_150 = 16'd1200;
            8'd9:   G_mul_150 = 16'd1350;
            8'd10:  G_mul_150 = 16'd1500;
            default: G_mul_150 = G * 150;
        endcase

        case (B)
            8'd0:   B_mul_29 = 16'd0;
            8'd1:   B_mul_29 = 16'd29;
            8'd2:   B_mul_29 = 16'd58;
            8'd3:   B_mul_29 = 16'd87;
            8'd4:   B_mul_29 = 16'd116;
            8'd5:   B_mul_29 = 16'd145;
            8'd6:   B_mul_29 = 16'd174;
            8'd7:   B_mul_29 = 16'd203;
            8'd8:   B_mul_29 = 16'd232;
            8'd9:   B_mul_29 = 16'd261;
            8'd10:  B_mul_29 = 16'd290;
            default: B_mul_29 = B * 29;
        endcase

        y_sum_stage1 = R_mul_77 + G_mul_150 + B_mul_29;
    end

    // Block 3: Cb Component Calculation (Sequential Pipeline Stage 1)
    logic [15:0] R_mul_43, G_mul_85, B_mul_128;
    logic [15:0] cb_sum_stage1;

    always_comb begin
        case (R)
            8'd0:   R_mul_43 = 16'd0;
            8'd1:   R_mul_43 = 16'd43;
            8'd2:   R_mul_43 = 16'd86;
            default: R_mul_43 = R * 43;
        endcase

        case (G)
            8'd0:   G_mul_85 = 16'd0;
            8'd1:   G_mul_85 = 16'd85;
            8'd2:   G_mul_85 = 16'd170;
            default: G_mul_85 = G * 85;
        endcase

        case (B)
            8'd0:   B_mul_128 = 16'd0;
            8'd1:   B_mul_128 = 16'd128;
            8'd2:   B_mul_128 = 16'd256;
            default: B_mul_128 = B * 128;
        endcase

        cb_sum_stage1 = B_mul_128 - R_mul_43 - G_mul_85 + 16'd32768;
    end

    // Block 4: Cr Component Calculation (Sequential Pipeline Stage 1)
    logic [15:0] R_mul_128, G_mul_107, B_mul_21;
    logic [15:0] cr_sum_stage1;

    always_comb begin
        case (R)
            8'd0:   R_mul_128 = 16'd0;
            8'd1:   R_mul_128 = 16'd128;
            8'd2:   R_mul_128 = 16'd256;
            default: R_mul_128 = R * 128;
        endcase

        case (G)
            8'd0:   G_mul_107 = 16'd0;
            8'd1:   G_mul_107 = 16'd107;
            8'd2:   G_mul_107 = 16'd214;
            default: G_mul_107 = G * 107;
        endcase

        case (B)
            8'd0:   B_mul_21 = 16'd0;
            8'd1:   B_mul_21 = 16'd21;
            8'd2:   B_mul_21 = 16'd42;
            default: B_mul_21 = B * 21;
        endcase

        cr_sum_stage1 = R_mul_128 - G_mul_107 - B_mul_21 + 16'd32768;
    end

    // Block 5: Pipeline Registers (Sequential)
    logic [15:0] y_sum_reg, cb_sum_reg, cr_sum_reg;
    logic        pixel_valid_reg;

    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: begin
                y_sum_reg <= 16'd0;
                cb_sum_reg <= 16'd0;
                cr_sum_reg <= 16'd0;
                pixel_valid_reg <= 1'b0;
            end
            1'b1: begin
                case (pixel_valid)
                    1'b1: begin
                        y_sum_reg <= y_sum_stage1;
                        cb_sum_reg <= cb_sum_stage1;
                        cr_sum_reg <= cr_sum_stage1;
                        pixel_valid_reg <= 1'b1;
                    end
                    default: begin
                        y_sum_reg <= y_sum_reg;
                        cb_sum_reg <= cb_sum_reg;
                        cr_sum_reg <= cr_sum_reg;
                        pixel_valid_reg <= 1'b0;
                    end
                endcase
            end
        endcase
    end

    // Block 6: Final Shift and Clipping (Combinational)
    logic [9:0] Y_out, Cb_out, Cr_out;

    always_comb begin
        // Y = (y_sum_reg >> 8), clip to 10-bit range
        case (y_sum_reg[15:8])
            8'd0:   Y_out = 10'd0;
            8'd1:   Y_out = 10'd1;
            8'd2:   Y_out = 10'd2;
            8'd3:   Y_out = 10'd3;
            8'd4:   Y_out = 10'd4;
            8'd5:   Y_out = 10'd5;
            8'd6:   Y_out = 10'd6;
            8'd7:   Y_out = 10'd7;
            8'd8:   Y_out = 10'd8;
            8'd9:   Y_out = 10'd9;
            8'd10:  Y_out = 10'd10;
            default: begin
                case (y_sum_reg[15:8] < 8'd255)
                    1'b1: Y_out = {2'b0, y_sum_reg[15:8]};
                    default: Y_out = 10'd255;
                endcase
            end
        endcase

        // Cb = (cb_sum_reg >> 8), clip to 10-bit range
        case (cb_sum_reg[15:8])
            8'd0:   Cb_out = 10'd0;
            default: begin
                case (cb_sum_reg[15:8] < 8'd255)
                    1'b1: Cb_out = {2'b0, cb_sum_reg[15:8]};
                    default: Cb_out = 10'd255;
                endcase
            end
        endcase

        // Cr = (cr_sum_reg >> 8), clip to 10-bit range
        case (cr_sum_reg[15:8])
            8'd0:   Cr_out = 10'd0;
            default: begin
                case (cr_sum_reg[15:8] < 8'd255)
                    1'b1: Cr_out = {2'b0, cr_sum_reg[15:8]};
                    default: Cr_out = 10'd255;
                endcase
            end
        endcase
